	@Test
	void mappedPhysicalJoinPreservesTheRetainedLogicalOmniEstimate() throws Exception {
		LmdbEstimatorRuntime runtime = mock(LmdbEstimatorRuntime.class);
		FrontierStatisticsView view = mock(FrontierStatisticsView.class);
		LmdbPackedCostModel costModel = mock(LmdbPackedCostModel.class);
		StatementPattern leftPattern = new StatementPattern(
				Var.of("s"), Var.of("leftPredicate", VF.createIRI("urn:test:physical:left")), Var.of("leftObject"));
		StatementPattern rightPattern = new StatementPattern(
				Var.of("s"), Var.of("rightPredicate", VF.createIRI("urn:test:physical:right")), Var.of("rightObject"));
		PackedCostTestSupport.BinaryCostCall call = PackedCostTestSupport.binaryOperator(defaultGraph(),
				new Join(leftPattern, rightPattern));
		PackedCostSession delegate = new PackedCostSession() {
			@Override
			public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
				output.setRows(relationId == call.leftRelationId() ? 100.0d : 200.0d, 200.0d);
				output.setEvidenceGuarantee(EvidenceGuarantee.DATABASE_EXACT);
			}

			@Override
			public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
			}

			@Override
			public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
			}

			@Override
			public boolean supportsPhysicalJoinRefinement() {
				return false;
			}
		};
		AtomicInteger logicalRefinements = new AtomicInteger();
		when(costModel.refineMappedIntermediateJoin(
				eq(call.query()), any(int[].class), any(int[].class), any(EvidenceStateSummary.class),
				any(int[].class), any(EvidenceStateSummary.class), anyBoolean(), any(PackedCostEstimate.class)))
						.thenAnswer(invocation -> {
							PackedCostEstimate estimate = invocation.getArgument(7);
							double rows = logicalRefinements.incrementAndGet() == 1 ? 25.0d : 40.0d;
							estimate.setContextualRows(rows, rows);
							estimate.setEstimateProvenance("frontier-v2-omni-subgraph", "frontier_v2_mapped_join");
							estimate.setEvidenceGuarantee(EvidenceGuarantee.MEASURE_UNBIASED);
							estimate.putPlannedDoubleMetric("plannedFrontierLowerRows", rows * 0.8d);
							estimate.putPlannedDoubleMetric("plannedFrontierUpperRows", rows * 1.2d);
							estimate.putPlannedDoubleMetric("plannedFrontierConfidence", 0.95d);
							return true;
						});

		try (PackedCostSession session = new LmdbFrontierStatisticsCostSession(
				delegate, costModel, view, call.query(), runtime, true)) {
			assertTrue(session.supportsPhysicalJoinRefinement(),
					"the query-local mapped session must enroll its physically refined joins in costed winner selection");
			PackedCostEstimate left = new PackedCostEstimate();
			PackedCostEstimate right = new PackedCostEstimate();
			session.estimateLeaf(call.leftRelationId(), call.emptyContext(), left);
			session.estimateLeaf(call.rightRelationId(), call.emptyContext(), right);
			PackedCostEstimate joined = new PackedCostEstimate();
			joined.setContextualRows(100.0d, 200.0d);
			PackedCostContext joinContext = call.operatorContext(
					left.outputRows(), right.outputRows(), left.evidenceStateId(), right.evidenceStateId());
			session.refineIntermediateJoin(joinContext, joined);

			assertEquals(25.0d, joined.outputRows(), 0.0d);
			int retainedStateId = joined.evidenceStateId();
			PackedCostTestSupport.refineIndependentHash(session,
					call.hashOperatorContext(left.outputRows(), right.outputRows(),
							left.evidenceStateId(), right.evidenceStateId(), 1, 1),
					joined);

			assertEquals(25.0d, joined.outputRows(), 0.0d,
					"physical costing must not reconstruct and replace the retained logical Omni cardinality");
			assertEquals(retainedStateId, joined.evidenceStateId(),
					"the physical implementation must retain the logical candidate's evidence lineage");
			assertEquals(1, logicalRefinements.get(),
					"the mapped logical join estimator must run only for the logical event");
		}
	}

	@Test
	void mappedFiniteDomainUsesProjectedDistinctWhenConcreteWitnessIntervalsAreWider() throws Exception {
		LmdbEstimatorRuntime runtime = mock(LmdbEstimatorRuntime.class);
		LmdbStatisticsService statistics = mock(LmdbStatisticsService.class);
		FrontierStatisticsStatus status = mock(FrontierStatisticsStatus.class);
		FrontierStatisticsView view = mock(FrontierStatisticsView.class);
		ValueStore valueStore = mock(ValueStore.class);
		when(runtime.statisticsService()).thenReturn(statistics);
		when(runtime.valueStore()).thenReturn(valueStore);
		when(runtime.frontierSettings()).thenReturn(
				LmdbFrontierPlannerSettings.from(new LmdbStoreConfig()
						.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)));
		when(statistics.status()).thenReturn(status);
		when(status.availability()).thenReturn(FrontierStatisticsAvailability.READY);
		when(status.fallbackReason()).thenReturn(FrontierFallbackReason.NONE);
		when(statistics.openCurrentView()).thenReturn(view);
		when(view.ready()).thenReturn(true);
		Answer<?> factorCostAnswer = invocation -> {
			BindingSetAssignment assignment = invocation.getArgument(0);
			double count = 0.0d;
			for (BindingSet ignored : assignment.getBindingSets()) {
				count++;
			}
			return Optional.of(new JoinFactorCostModel.FactorCostEstimate(count, count));
		};
		when(runtime.factorCost(any(BindingSetAssignment.class), any())).thenAnswer(factorCostAnswer);
		when(runtime.factorCost(any(BindingSetAssignment.class), any(), nullable(LmdbFilterReadContext.class)))
				.thenAnswer(factorCostAnswer);
		var predicate = VF.createIRI("urn:test:sparse-finite-prefix:name");
		when(valueStore.getId(predicate)).thenReturn(101L);
		List<BindingSet> rows = new ArrayList<>();
		for (int ordinal = 0; ordinal < 4; ordinal++) {
			var subject = VF.createIRI("urn:test:sparse-finite-prefix:user:" + ordinal);
			when(valueStore.getId(subject)).thenReturn(201L + ordinal);
			rows.add(new ListBindingSet(List.of("subject"), subject));
		}
		BindingSetAssignment finiteSubjects = new BindingSetAssignment();
		finiteSubjects.setBindingNames(new LinkedHashSet<>(List.of("subject")));
		finiteSubjects.setBindingSets(rows);
		StatementPattern name = new StatementPattern(
				Var.of("subject"), Var.of("namePredicate", predicate), Var.of("name"));
		PackedCostTestSupport.PairCostCall call = PackedCostTestSupport.connectedFiniteFactor(defaultGraph(), name,
				finiteSubjects);
		when(view.estimateLeaf(any())).thenAnswer(invocation -> {
			FrontierLeafProbe probe = invocation.getArgument(0);
			if ((probe.boundMask() & FrontierLeafProbe.SUBJECT) != 0) {
				return new FrontierLeafEstimate(204.0d, 0.0d, 204.0d, 0.86d,
						"frontier-v2-count-min-supported-omni", FrontierFallbackReason.NONE);
			}
			return new FrontierLeafEstimate(816.0d, 816.0d, 816.0d, 1.0d,
					"frontier-v2-exact", FrontierFallbackReason.NONE);
		});
		when(view.estimateProjectedDistinct(any(), anyInt())).thenReturn(816.0d);

		try (PackedCostSession session = new LmdbPackedCostModel(runtime, OptionalLong.empty(), true)
				.openSession(call.query())) {
			PackedCostEstimate assignment = new PackedCostEstimate();
			session.estimateLeaf(call.factorRelationId(), call.emptyContext(), assignment);
			PackedCostEstimate statement = new PackedCostEstimate();
			session.estimateLeaf(call.prefixRelationId(), call.emptyContext(), statement);
			int statementEvidenceStateId = statement.evidenceStateId();

			assertEquals(4.0d, assignment.outputRows(), 0.0d,
					"the mock provider must actually supply its immutable four-row VALUES leaf");
			assertTrue(assignment.evidenceStateId() > 0, "the prefix state must belong to this native session");
			session.appendFactor(call.prefixRelationId(),
					call.reversePrefixContext(4.0d, assignment.evidenceStateId()), statement);

			assertEquals(4.0d, statement.outputRows(), 0.0d,
					"the tighter projected-distinct interval must beat collision-dominated concrete probes");
			assertFalse(statement.hasComponentOutputRows(),
					"a mapped transition already includes the complete finite prefix and must retain its join evidence");
			assertTrue(statement.estimateSource().contains("projected-distinct-conditional"),
					"the selected estimate should retain its bounded mapped-statistics provenance");

			PackedCostEstimate refined = new PackedCostEstimate();
			refined.setContextualRows(statement.outputRows(), statement.workRows());
			session.refineIntermediateJoin(
					call.intermediateJoinContext(assignment.outputRows(), statement.evidenceStateId(),
							assignment.outputRows(), 816.0d,
							assignment.evidenceStateId(), statementEvidenceStateId),
					refined);

			assertEquals(4.0d, refined.outputRows(), 0.0d,
					"intermediate refinement must recover the retained candidate interval when physical join "
							+ "composition carries only its scalar rows");
			assertTrue(refined.estimateSource().contains("projected-distinct-conditional"),
					"intermediate refinement should preserve the selected estimator provenance");
		}
	}

