	private static void checkFilteredFinitePrefix(boolean qualified) throws Exception {
		LmdbEstimatorRuntime runtime = mock(LmdbEstimatorRuntime.class);
		LmdbStatisticsService statistics = mock(LmdbStatisticsService.class);
		FrontierStatisticsStatus status = mock(FrontierStatisticsStatus.class);
		FrontierStatisticsView view = mock(FrontierStatisticsView.class);
		ValueStore valueStore = mock(ValueStore.class);
		when(runtime.statisticsService()).thenReturn(statistics);
		when(runtime.valueStore()).thenReturn(valueStore);
		when(runtime.frontierSettings()).thenReturn(
				LmdbFrontierPlannerSettings.from(new LmdbStoreConfig()
						.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)));
		when(statistics.status()).thenReturn(status);
		when(status.availability()).thenReturn(FrontierStatisticsAvailability.READY);
		when(status.fallbackReason()).thenReturn(FrontierFallbackReason.NONE);
		when(statistics.openCurrentView()).thenReturn(view);
		when(view.ready()).thenReturn(true);
		Answer<?> factorCostAnswer = invocation -> {
			BindingSetAssignment assignment = invocation.getArgument(0);
			double count = 0.0d;
			for (BindingSet ignored : assignment.getBindingSets()) {
				count++;
			}
			return Optional.of(new JoinFactorCostModel.FactorCostEstimate(count, count));
		};
		when(runtime.factorCost(any(BindingSetAssignment.class), any())).thenAnswer(factorCostAnswer);
		when(runtime.factorCost(any(BindingSetAssignment.class), any(), nullable(LmdbFilterReadContext.class)))
				.thenAnswer(factorCostAnswer);
		var predicate = VF.createIRI("urn:test:restricted-finite-prefix:name");
		when(valueStore.getId(predicate)).thenReturn(101L);
		List<BindingSet> rows = new ArrayList<>();
		for (int ordinal = 0; ordinal < 4; ordinal++) {
			var subject = VF.createIRI("urn:test:restricted-finite-prefix:user:" + ordinal);
			when(valueStore.getId(subject)).thenReturn(201L + ordinal);
			if (qualified) {
				rows.add(new ListBindingSet(List.of("subject"), subject));
			} else {
				MapBindingSet row = new MapBindingSet(1);
				row.setBinding("subject", subject);
				rows.add(row);
			}
		}
		BindingSetAssignment finiteSubjects = new BindingSetAssignment();
		finiteSubjects.setBindingNames(new LinkedHashSet<>(List.of("subject")));
		finiteSubjects.setBindingSets(rows);
		StatementPattern name = new StatementPattern(
				Var.of("subject"), Var.of("namePredicate", predicate), Var.of("name"));
		Filter filtered = new Filter(finiteSubjects, new Or(
				new Compare(Var.of("subject"), new ValueConstant(rows.get(0).getValue("subject")),
						Compare.CompareOp.EQ),
				new Compare(Var.of("subject"), new ValueConstant(rows.get(1).getValue("subject")),
						Compare.CompareOp.EQ)));
		TupleExpr prefix = qualified ? filtered : finiteSubjects;
		var call = PackedCostTestSupport.binaryOperator(defaultGraph(), new Join(prefix, name));
		int assignmentId = qualified ? call.query().childRelationId(call.leftRelationId(), 0) : call.leftRelationId();
		if (qualified) {
			long actualRows = 0L;
			TripleSource triples = mock(TripleSource.class);
			when(triples.getValueFactory()).thenReturn(VF);
			var evaluator = new DefaultEvaluationStrategy(triples, null);
			try (var result = evaluator.precompile(new QueryRoot(filtered.clone()))
					.evaluate(EmptyBindingSet.getInstance())) {
				while (result.hasNext()) {
					result.next();
					actualRows++;
				}
			}
			assertEquals(2L, actualRows, "the actual finite FILTER supplies the complete two-row input bag");
		}
		when(view.estimateLeaf(any())).thenAnswer(invocation -> {
			FrontierLeafProbe probe = invocation.getArgument(0);
			double estimate = (probe.boundMask() & FrontierLeafProbe.SUBJECT) != 0 ? 1.0d : 100.0d;
			return new FrontierLeafEstimate(estimate, estimate, estimate, 1.0d,
					"frontier-v2-omni-leaf", FrontierFallbackReason.NONE);
		});
		when(view.estimateProjectedDistinct(any(), anyInt())).thenReturn(100.0d);

		try (PackedCostSession session = new LmdbPackedCostModel(runtime, OptionalLong.empty(), true)
				.openSession(call.query())) {
			PackedCostEstimate assignment = new PackedCostEstimate();
			session.estimateLeaf(assignmentId, call.emptyContext(), assignment);
			assertEquals(4.0d, assignment.outputRows(), 0.0d);
			PackedCostEstimate statement = new PackedCostEstimate();
			session.estimateLeaf(call.rightRelationId(), call.emptyContext(), statement);
			if (qualified) {
				assertTrue(assignment.evidenceStateId() > 0);
				PackedCostEstimate filteredInput = new PackedCostEstimate();
				filteredInput.setContextualRows(2.0d, 2.0d);
				session.refineOperator(call.leftRelationId(), call.operatorContext(4.0d, Double.NaN,
						assignment.evidenceStateId(), 0), filteredInput);
				assertTrue(filteredInput.evidenceStateId() > 0);
				assertTrue(filteredInput.runtimeFeedbackContract().admits(RuntimeFeedbackContract.ADMIT_LOGICAL));
				PackedCostEstimate joined = new PackedCostEstimate();
				joined.setContextualRows(2.0d, 2.0d);
				session.refineIntermediateJoin(call.operatorContext(2.0d, statement.outputRows(),
						filteredInput.evidenceStateId(), statement.evidenceStateId()), joined);
				assertEquals(2.0d, joined.outputRows(), 0.0d,
						"the authenticated complete JOIN summary must preserve its restricted input population");
				assertFalse("frontier-v2-omni-finite-domain".equals(joined.estimateSource()),
						"an unfiltered finite-domain reconstruction cannot describe a filtered prefix bag");
				assertTrue(joined.runtimeFeedbackContract().admits(RuntimeFeedbackContract.ADMIT_LOGICAL));
			} else {
				PackedCostContext context = PackedCostTestSupport.restrictedPrefixContext(
						new int[] { assignmentId }, 1, 2.0d, assignment.evidenceStateId());
				int calls = mockingDetails(view).getInvocations().size();
				double isolatedWork = statement.workRows();
				session.appendFactor(call.rightRelationId(), context, statement);
				assertEquals(100.0d, statement.outputRows(), 0.0d);
				assertEquals(isolatedWork, statement.workRows(), 0.0d);
				assertEquals(calls, mockingDetails(view).getInvocations().size());
				assertEquals(0, statement.evidenceStateId());
				assertFalse(statement.runtimeFeedbackContract() != null
						&& statement.runtimeFeedbackContract().admits(RuntimeFeedbackContract.ADMIT_LOGICAL));
				assertFalse(statement.runtimeFeedbackContract() != null
						&& statement.runtimeFeedbackContract().admits(RuntimeFeedbackContract.ADMIT_LIFECYCLE));
			}
		}
	}

	@Test
	void mappedV2SessionBoundsAggregateSubgraphEvidenceWorkByQuerySize() throws Exception {
		LmdbEstimatorRuntime runtime = mock(LmdbEstimatorRuntime.class);
		LmdbStatisticsService statistics = mock(LmdbStatisticsService.class);
		FrontierStatisticsStatus status = mock(FrontierStatisticsStatus.class);
		FrontierStatisticsView view = mock(FrontierStatisticsView.class);
		ValueStore valueStore = mock(ValueStore.class);
		when(runtime.statisticsService()).thenReturn(statistics);
		when(runtime.valueStore()).thenReturn(valueStore);
		when(runtime.frontierSettings()).thenReturn(
				LmdbFrontierPlannerSettings.from(new LmdbStoreConfig()
						.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)));
		when(statistics.status()).thenReturn(status);
		when(status.availability()).thenReturn(FrontierStatisticsAvailability.READY);
		when(status.fallbackReason()).thenReturn(FrontierFallbackReason.NONE);
		when(statistics.openCurrentView()).thenReturn(view);
		when(view.ready()).thenReturn(true);
		when(view.estimateLeaf(any())).thenReturn(new FrontierLeafEstimate(
				100.0d, 80.0d, 120.0d, 0.95d, "frontier-v2-omni-leaf", FrontierFallbackReason.NONE));
		when(view.estimateJoin(any())).thenReturn(new FrontierJoinEstimate(
				25.0d, 10.0d, 40.0d, 0.90d, "frontier-v2-omni-bridge", FrontierFallbackReason.NONE));
		when(view.estimateSubgraph(any())).thenReturn(new FrontierJoinEstimate(
				25.0d, 10.0d, 40.0d, 0.90d, "frontier-v2-omni-path", FrontierFallbackReason.NONE));
		when(view.estimateConditionalJoin(any(), anyDouble())).thenReturn(new FrontierJoinEstimate(
				1.0d, 0.5d, 2.0d, 0.90d, "frontier-v2-omni-center-conditional", FrontierFallbackReason.NONE));
		when(view.estimateProjectedDistinct(any(), anyInt())).thenReturn(Double.NaN);
		when(runtime.packedTransitionRows(any(), any(), any(Double.class), any(Double.class))).thenReturn(25.0d);
		int patternCount = 12;
		StatementPattern[] patterns = new StatementPattern[patternCount];
		for (int pattern = 0; pattern < patternCount; pattern++) {
			var predicate = VF.createIRI("urn:test:session-work:" + pattern);
			when(valueStore.getId(predicate)).thenReturn(100L + pattern);
			patterns[pattern] = new StatementPattern(
					Var.of("s"), Var.of("predicate" + pattern, predicate), Var.of("object" + pattern));
		}
		PackedCostTestSupport.StatementOnlyChainCostCall call = PackedCostTestSupport
				.statementOnlyFactorChain(defaultGraph(), patterns);

		try (PackedCostSession session = new LmdbPackedCostModel(runtime, OptionalLong.empty(), true)
				.openSession(call.query())) {
			for (int prefix = 1; prefix < patternCount; prefix++) {
				PackedCostEstimate estimate = new PackedCostEstimate();
				estimate.setRows(100.0d, 100.0d);
				session.appendFactor(call.relationId(prefix), call.prefixContext(prefix, 100.0d), estimate);
			}
		}

		long factorWork = mockingDetails(view).getInvocations()
				.stream()
				.mapToLong(invocation -> switch (invocation.getMethod().getName()) {
				case "estimateJoin" -> 2L;
				case "estimateSubgraph" -> invocation.<FrontierJoinProgram>getArgument(0).patternCount();
				default -> 0L;
				})
				.sum();
		assertTrue(factorWork <= (long) LmdbPackedCostModel.MAX_MAPPED_LINEAGE_FACTOR_WORK_PER_PATTERN * patternCount,
				() -> "mapped evidence work must stay linear in query size, observed factor-work " + factorWork);
	}

